        x,
        y,
        vx: Math.cos(a) * sp,
        vy: Math.sin(a) * sp - 60,
        life: randRange(0.3, 0.6),
        t: 0,
        size: randRange(2, 5),
        color: colors[Math.floor(Math.random() * colors.length)],
