/**
 * utils.js — hàm tiện ích dùng chung cho toàn package.
 */

const clamp = (v, min, max) => Math.min(max, Math.max(min, v));

const lerp = (a, b, t) => a + (b - a) * t;

const randRange = (min, max) => min + Math.random() * (max - min);

