    const left = el("div", "vr-start-left");

    const logo = el("div", "vr-logo");
    logo.appendChild(el("div", "l1", "VOID"));
    logo.appendChild(el("div", "l2", "RUNNER"));
    const l3 = el("div", "l3");
    l3.appendChild(el("span", "", "404"));
    logo.appendChild(l3);
    left.appendChild(logo);

