    const up = keys.isDown("ArrowUp") || keys.isDown("KeyW");
    const down = keys.isDown("ArrowDown") || keys.isDown("KeyS");
    const drift = keys.isDown("Space");
    const nitro = keys.isDown("ShiftLeft") || keys.isDown("ShiftRight");

