    g.roundRect(-19, -11, 38, 22, 7);
    g.fill();
    g.strokeStyle = "rgba(60,44,4,0.8)";
    g.lineWidth = 1.4;
    g.stroke();
    // kính trước + sau
    g.fillStyle = "#141006";
    g.beginPath();
    g.roundRect(3, -8.5, 8, 17, 3);
    g.fill();
    g.beginPath();
    g.roundRect(-11, -8.5, 7, 17, 3);
    g.fill();
