    g.fillRect(6, -13, 10, 4.5);
    g.fillRect(-15, 8.5, 10, 4.5);
    g.fillRect(6, 8.5, 10, 4.5);
    // thân xe tối
    const grad = g.createLinearGradient(0, -11, 0, 11);
    grad.addColorStop(0, "#1c2547");
    grad.addColorStop(0.5, "#101731");
    grad.addColorStop(1, "#0a0f22");
    g.fillStyle = grad;
