    g.fill();
    g.restore();
    // cánh gió sau
    g.fillStyle = "#151d3c";
    g.beginPath();
    g.roundRect(-21, -10, 4, 20, 2);
    g.fill();
    g.strokeStyle = "rgba(255,46,230,0.7)";
    g.lineWidth = 1;
    g.stroke();
    // đèn pha
    g.save();
    g.shadowColor = "#eafcff";
    g.shadowBlur = 10;
    g.fillStyle = "#eafcff";
    g.fillRect(18, -8, 3, 4.6);
    g.fillRect(18, 3.4, 3, 4.6);
    g.restore();
    // đèn hậu
    g.save();
    g.shadowColor = "#ff3b57";
    g.shadowBlur = 8;
    g.fillStyle = "#ff3b57";
    g.fillRect(-21.5, -8, 3, 4.6);
