        const row = el("div", "exp-setrow");
        row.appendChild(el("span", "", "TRẠNG THÁI"));
        row.appendChild(el("span", "val", `CẤP ${arena.level} · HẠ ${arena.kills} · CÒN ${formatTime(Math.max(0, MATCH_TIME - arena.time))}`));
        box.appendChild(row);
