    mode = "play";
    frame.clearScreen();
    frame.setPaused(false);
    ctx.onMatchStart();
    frame.banner(`MÀN ${String(idx + 1).padStart(2, "0")} — ${LEVELS[idx].name}`);
    ctx.audio.play("start");
