        row.appendChild(el("span", "", "TIẾN TRÌNH"));
        row.appendChild(el("span", "val", `MÀN ${levelIdx + 1}/10 · ${formatNumber(m.score)} ĐIỂM · ${m.lives} MẠNG`));
