      if (m.acc > 92 && m.wpm > 24) sess.adaptFactor = Math.min(1.35, sess.adaptFactor + 0.06);
      else if (m.acc < 82 || m.wpm < 12) sess.adaptFactor = Math.max(0.8, sess.adaptFactor - 0.06);
