  chevron:
    "data:image/webp;base64,",
  chipActive:
    "data:image/webp;base64,",
  chipCyan:
    "data:image/webp;base64,",
  chipPink:
    "data:image/webp;base64,",
  chipViolet:
    "data:image/webp;base64,",
  chipWhite:
    "data:image/webp;base64,",
  dangerLine:
    "data:image/webp;base64,",
  decoL:
    "data:image/webp;base64,",
  decoR:
    "data:image/webp;base64,",
  warnTri:
    "data:image/webp;base64,",
