      setFlipper(sim, "right", keys.isDown("ArrowRight") || keys.isDown("KeyD") || touch.right.size > 0);
      // plunger: giữ SPACE / giữ vùng lane
      const hold = keys.isDown("Space") || touch.plunger.size > 0;
