    level: 1,
    score: 0,
    moves: 0,
    hints: HINTS_PER_RUN,
    combo: 0,
    maxCombo: 0,
    matches: 0,
    cursor: 0,
    cursorOn: false,
    hintT: 0,
    levelClearT: 0,
