  drawBug(150, 44, "#ffd23f", false, 0.9);
  drawBug(250, 70, "#3be8ff", false, 0.8);
  drawBug(206, 140, "#ff5d6b", true);
  drawBug(96, 148, "#4bf584", false, 1.05);
  drawBug(286, 158, "#ffd23f", false, 0.85);

  // Tâm ngắm
  ctx.strokeStyle = "rgba(200,245,66,.9)";
  ctx.lineWidth = 2;
  ctx.beginPath();
