const PAINTERS = {
  runner: runnerArt,
  "bug-hunter": bugArt,
  "stack-tower": stackArt,
  snake: snakeArt,
  strike: strikeArt,
  "portal-puzzle": portalArt,
  "neon-drift": driftArt,
  "cyber-defense": defenseArt,
  "rogue-arena": rogueArt,
  "rhythm-hack": rhythmArt,
  "void-runner": voidRunnerArt,
  "brick-breaker": brickBreakerArt,
  "laser-maze": laserMazeArt,
  "pixel-golf": pixelGolfArt,
  "typing-rush": typingRushArt,
  "astro-patrol": astroPatrolArt,
  "neon-pinball": pinballArt,
  "gravity-flip": gravityFlipArt,
  "memory-matrix": memoryMatrixArt,
  "cyber-goal": cyberGoalArt,
  "stealth-escape": stealthEscapeArt,
};

/** Vẽ preview của một game lên canvas trong card. */
function paintPreview(gameId, canvas) {
  const painter = PAINTERS[gameId];
  if (!painter) return;
  const ctx = setup(canvas);
  painter(ctx);
}

exports.paintPreview = paintPreview;
